node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createRepository } from './src/repository.mjs';
import { collectAll } from './src/collect.mjs';
const rows = [
  { id: 1, deleted: true }, { id: 2, deleted: true },
  { id: 3 }, { id: 4, deleted: true }, { id: 5 },
];
const repository = createRepository(rows);
assert.deepEqual(await repository.page({ cursor: 2, limit: 2 }), {
  items: [{ id: 3 }, { id: 4, deleted: true }].filter(row => !row.deleted),
  nextCursor: null,
});
assert.deepEqual(await collectAll(createRepository(rows), { limit: 2 }), [{ id: 3 }, { id: 5 }]);
await assert.rejects(collectAll({ page: async () => ({ items: [], nextCursor: 7 }) }), /Repeated cursor/);
await assert.rejects(collectAll({ page: async ({ cursor }) => ({ items: [], nextCursor: cursor === null ? 1 : cursor + 1 }) }, { maxPages: 2 }), /Page budget exhausted/);
console.log('pagination contract checks passed');
EOF

